    private void cleanupEditor()throws Exception{if(editor!=null){drainEditor();ui(()->call(editor,"unbind"));drainEditor();}if(draftFile!=null)Files.deleteIfExists(draftFile.toPath());if(fixtureFile!=null)Files.deleteIfExists(fixtureFile.toPath());fixtureRemoved=(draftFile==null||!draftFile.exists())&&(fixtureFile==null||!fixtureFile.exists());if(!fixtureRemoved)throw new AssertionError("Owned125 fixture/draft remains");}
    private void set(Object o,String name,Object value)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);f.set(o,value);return;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}

    private Dialog open(Object region,AtomicReference<Object> committed)throws Exception{Dialog[] result={null};ui(()->{Class<?> regionType=loader.loadClass("cc.huevia.ncp.AdjustmentRegion");result[0]=(Dialog)loader.loadClass("cc.huevia.ui.PhotoBrushDialog").getConstructor(Activity.class,Bitmap.class,regionType,Consumer.class).newInstance(activity,source,region,(Consumer<Object>)committed::set);dialogs.add(result[0]);result[0].show();});until(()->((View)get(result[0],"photo")).getWidth()>0&&((RectF)get(get(result[0],"photo"),"frame")).width()>0,"dialog-frame-ready");return result[0];}
    private Object settings(Dialog d)throws Exception{return call(d,"settings");}private int strokes(Object region)throws Exception{return((List<?>)get(region,"strokes")).size();}
    private int step(Object d,String f)throws Exception{return((Number)get(d,f)).intValue();}
    private Frame release(Dialog d,long down)throws Exception{return captureAction(d,"previewFlashStep",0,()->{View p=(View)get(d,"photo");RectF f=(RectF)get(p,"frame");touch(p,down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,f.left+f.width()*.8f,f.centerY());});}
    private Frame captureAction(Dialog d,String field,int expected,Work action)throws Exception{Frame[] frame={null};ui(()->{action.run();check(field+"-expected-"+expected,step(d,field)==expected);frame[0]=new Frame(render(d),SystemClock.uptimeMillis());});return frame[0];}
    private Frame await(Dialog d,String field,int expected)throws Exception{long deadline=SystemClock.uptimeMillis()+6000;while(SystemClock.uptimeMillis()<deadline){Frame[] f={null};ui(()->{if(step(d,field)==expected)f[0]=new Frame(render(d),SystemClock.uptimeMillis());});if(f[0]!=null)return f[0];SystemClock.sleep(5);}throw new AssertionError("Timed out "+field+"="+expected);}
    private Bitmap draw(Dialog d)throws Exception{Bitmap[] b={null};ui(()->b[0]=render(d));return b[0];}
    private Bitmap render(Dialog d)throws Exception{View p=(View)get(d,"photo");Bitmap b=Bitmap.createBitmap(p.getWidth(),p.getHeight(),Bitmap.Config.ARGB_8888);p.draw(new Canvas(b));captures.add(b);return b;}
    private static final class Frame{final Bitmap image;final long at;Frame(Bitmap b,long t){image=b;at=t;}}
    private void paint(Dialog d,long down,boolean release)throws Exception{View p=(View)get(d,"photo");RectF f=(RectF)get(p,"frame");touch(p,down,down,MotionEvent.ACTION_DOWN,f.left+f.width()*.2f,f.centerY());for(int i=1;i<=10;i++)touch(p,down,down+i*3,MotionEvent.ACTION_MOVE,f.left+f.width()*(.2f+.6f*i/10),f.centerY());}
    private void touch(View v,long down,long time,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,time,action,x,y,0);try{v.onTouchEvent(e);}finally{e.recycle();}}
    private void multi(View v,long down,long time,int action,float x0,float y0,float x1,float y1){MotionEvent.PointerProperties[] props={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] coords={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i].pressure=1;coords[i].size=1;}coords[0].x=x0;coords[0].y=y0;coords[1].x=x1;coords[1].y=y1;MotionEvent e=MotionEvent.obtain(down,time,action,2,props,coords,0,0,1,1,0,0,0,0);try{v.onTouchEvent(e);}finally{e.recycle();}}
    private void compareFrames(Dialog d,Bitmap plain,Bitmap soft,Bitmap strong)throws Exception{int w=plain.getWidth(),h=plain.getHeight();int[] a=new int[w*h],b=a.clone(),c=a.clone();plain.getPixels(a,0,w,0,0,w,h);soft.getPixels(b,0,w,0,0,w,h);strong.getPixels(c,0,w,0,0,w,h);RectF f=new RectF((RectF)get(get(d,"photo"),"frame"));float radius=(float)(.04*Math.min(960,720)/960*f.width())+f.width()*6/320;RectF affected=new RectF(f.left+f.width()*.2f-radius,f.centerY()-radius,f.left+f.width()*.8f+radius,f.centerY()+radius);long protectedCount=0,changed=0;double softDelta=0,strongDelta=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=y*w+x;if(!affected.contains(x+.5f,y+.5f)){protectedCount++;if(a[i]!=c[i])throw new AssertionError("Overlay escaped selected stroke at "+x+","+y);}if(a[i]!=b[i]){changed++;softDelta+=delta(a[i],b[i]);strongDelta+=delta(a[i],c[i]);}}check("strong-overlay-more-visible",changed>100&&strongDelta>softDelta*1.8);check("outside-overlay-unchanged",protectedCount>w*h/2);measurements.put(new JSONObject().put("case","strong-versus-existing-soft").put("changedPixels",changed).put("protectedPixels",protectedCount).put("outsideDifferences",0).put("strongToSoftTotalDeltaRatio",strongDelta/softDelta));}
    private int delta(int a,int b){return Math.abs(((a>>>16)&255)-((b>>>16)&255))+Math.abs(((a>>>8)&255)-((b>>>8)&255))+Math.abs((a&255)-(b&255));}
    private boolean same(Bitmap a,Bitmap b){return a.sameAs(b);}private void write(String name,Bitmap b)throws Exception{if("font1.3".equals(args.getString("mode")))return;try(OutputStream out=new FileOutputStream(new File(output,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}screenshots++;}
    private void screenshot(String name)throws Exception{if("font1.3".equals(args.getString("mode")))return;Bitmap b=getUiAutomation().takeScreenshot();try{write(name,b);}finally{b.recycle();}}
    private void ui(Work work)throws Exception{AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{work.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new RuntimeException(error.get());}
    private void until(Condition c,String label)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){if(c.test())return;SystemClock.sleep(10);}throw new AssertionError("Timeout "+label);}
    private void check(String label,boolean pass)throws Exception{checks.put(new JSONObject().put("name",label).put("pass",pass));if(!pass)throw new AssertionError(label);}
    private Object get(Object o,String name)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    private Object call(Object o,String name,Object...args)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){m.setAccessible(true);try{return m.invoke(o,args);}catch(IllegalArgumentException ignored){}}throw new NoSuchMethodException(name);}
    private Object callStatic(String type,String name,Object...args)throws Exception{return callClass(loader.loadClass(type),name,args);}
    private Object callClass(Class<?> type,String name,Object...args)throws Exception{for(Method m:type.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){m.setAccessible(true);return m.invoke(null,args);}throw new NoSuchMethodException(name);}
    private String sha(File f)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(f.toPath())));}private String bitmapSha(Bitmap b)throws Exception{int[] p=new int[b.getWidth()*b.getHeight()];b.getPixels(p,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());MessageDigest d=MessageDigest.getInstance("SHA-256");for(int v:p){d.update((byte)(v>>>24));d.update((byte)(v>>>16));d.update((byte)(v>>>8));d.update((byte)v);}return hex(d.digest());}
    private String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}private Throwable unwrap(Throwable e){while(e.getCause()!=null)e=e.getCause();return e;}
    private String shell(String text)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(text);InputStream in=new FileInputStream(fd.getFileDescriptor());ByteArrayOutputStream out=new ByteArrayOutputStream()){in.transferTo(out);return out.toString("UTF-8");}}
